-- ==========================================================================
-- PostGIS address_standardizer: Brazilian Gazetteer Dataset (br_gaz)
-- Data Provenance: Official IBGE Localidades (Municipalities and States of Brazil)
-- License: Public Domain / Open Government Data
-- ==========================================================================

CREATE TABLE IF NOT EXISTS br_gaz (
    id serial,
    seq integer,
    word text,
    stdword text,
    token integer, is_custom boolean NOT NULL DEFAULT true, CONSTRAINT pk_br_gaz PRIMARY KEY(id)
);

-- Upgrade protection for custom entries
DELETE FROM br_gaz WHERE is_custom = false;

-- Default is_custom to false for shipped entries
ALTER TABLE br_gaz ALTER COLUMN is_custom SET DEFAULT false;

